def sort_by_duration(playlist):
    """Returns the playlist sorted from shortest to longest song."""
    playlist_copy = playlist[:]  # Make a copy so the original is unchanged
    sorted_list = []
    while playlist_copy:
        # Find the song with the minimum duration
        shortest = playlist_copy[0]
        for song in playlist_copy:
            if song['duration'] < shortest['duration']:
                shortest = song
        sorted_list.append(shortest)
        playlist_copy.remove(shortest)
    return sorted_list
